#!/usr/bin/env sh
# fetch Bergamo Trasporti Est / Ovest / Sud (suburban consortia; operated by Arriva Italia, SAB Autoservizi, SAV Visinoni, SAI Autolinee, Autoservizi Locatelli) (IT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://raw.githubusercontent.com/jqueguiner/gtfs/main/synthesized/IT/bergamo/bergamo-trasporti-est-ovest-sud-suburban-consort/gtfs/"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
